const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1400, height: 1100 } });
await page.goto('http://localhost:4173/', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);

// 1. Перетаскиваем виджет «Продажи по категориям» (3-й) вниз влево
const dragHandles = await page.$$('.viz-widget__drag');
const box = await dragHandles[2].boundingBox();
await page.mouse.move(box.x + 8, box.y + 8);
await page.mouse.down();
await page.mouse.move(box.x + 8 - 300, box.y + 8 + 400, { steps: 12 });
await page.screenshot({ path: '/tmp/dnd-during.png' }); // во время drag — плейсхолдер
await page.mouse.up();
await page.waitForTimeout(400);

// 2. Удаляем виджет KPI через крестик
const closeBtns = await page.$$('button[title="Убрать виджет"]');
await closeBtns[0].click();
await page.waitForTimeout(300);

// 3. Добавляем его обратно через меню «Виджет»
await page.click('button:has-text("Виджет")');
await page.waitForTimeout(300);
await page.click('text=Ключевые метрики');
await page.waitForTimeout(400);

// 4. Переключаем «Выручка» в табличный вид
const toggleBtns = await page.$$('button[title="Показать таблицу"]');
await toggleBtns[0].click();
await page.waitForTimeout(300);

await page.screenshot({ path: '/tmp/dnd-after.png', fullPage: true });

// 5. Проверяем персистентность: перезагрузка должна сохранить раскладку
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/dnd-reloaded.png', fullPage: true });

await browser.close();
console.log('ok');

