import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1400, height: 1100 } });
await page.goto('http://localhost:4173/', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);

const readLayout = () =>
  page.evaluate(() => JSON.parse(localStorage.getItem('viz-dashboard-layout-v1')));

console.log('before:', JSON.stringify(await readLayout()));

// Drag categories (3rd handle) by -300px, +400px
const handles = await page.$$('.viz-widget__drag');
const box = await handles[2].boundingBox();
await page.mouse.move(box.x + 8, box.y + 8);
await page.mouse.down();
await page.mouse.move(box.x + 8 - 300, box.y + 8 + 400, { steps: 12 });
await page.mouse.up();
await page.waitForTimeout(400);
const after = await readLayout();
console.log('after drag:', JSON.stringify(after));

// Проверки
const overlaps = (a, b) =>
  a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
let bad = 0;
for (const a of after)
  for (const b of after)
    if (a.type !== b.type && overlaps(a, b)) {
      console.log('OVERLAP:', a.type, JSON.stringify(a), b.type, JSON.stringify(b));
      bad++;
    }
for (const i of after)
  if (i.x < 0 || i.y < 0 || i.x + i.w > 12) {
    console.log('OUT OF BOUNDS:', i.type, JSON.stringify(i));
    bad++;
  }
const cat = after.find((i) => i.type === 'categories');
console.log('categories moved to:', cat.x, cat.y, '(ожидалось примерно x=4, y=6-7)');
console.log(bad === 0 ? 'LAYOUT OK' : 'LAYOUT BROKEN');

// Resize: тянем ручку ресайза у revenue
const grips = await page.$$('.viz-widget__resize');
const g = await grips[1].boundingBox();
await page.mouse.move(g.x + 6, g.y + 6);
await page.mouse.down();
await page.mouse.move(g.x + 6 + 230, g.y + 6 + 170, { steps: 8 });
await page.mouse.up();
await page.waitForTimeout(400);
const afterResize = await readLayout();
const rev = afterResize.find((i) => i.type === 'revenue');
console.log('revenue after resize:', JSON.stringify(rev));
let bad2 = 0;
for (const a of afterResize)
  for (const b of afterResize)
    if (a.type !== b.type && overlaps(a, b)) bad2++;
console.log(bad2 === 0 ? 'RESIZE OK' : 'RESIZE BROKEN');

await browser.close();

