import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1400, height: 1100 } });
await page.goto('http://localhost:4173/', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);

// Resize первого виджета (kpi, виден без скролла): тянем ручку влево-вниз
const grips = await page.$$('.viz-widget__resize');
const g = await grips[0].boundingBox();
await page.mouse.move(g.x + 6, g.y + 6);
await page.mouse.down();
await page.mouse.move(g.x + 6 - 450, g.y + 6 + 170, { steps: 8 });
await page.mouse.up();
await page.waitForTimeout(400);
const layout = await page.evaluate(() =>
  JSON.parse(localStorage.getItem('viz-dashboard-layout-v1')),
);
console.log(JSON.stringify(layout));
const kpi = layout.find((i) => i.type === 'kpi');
console.log('kpi после resize:', kpi.w, 'x', kpi.h, '(было 12x2, ожидалось примерно 8x4)');

// персистентность после перезагрузки
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(500);
const layout2 = await page.evaluate(() =>
  JSON.parse(localStorage.getItem('viz-dashboard-layout-v1')),
);
console.log('после reload совпадает:', JSON.stringify(layout) === JSON.stringify(layout2));
await browser.close();

