import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1400, height: 1000 } });
await page.goto('http://localhost:4173/', { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(600);

// hover по линейному графику — перекрестие + тултип
const revenue = (await page.$$('.viz-widget'))[1];
const box = await revenue.boundingBox();
await page.mouse.move(box.x + box.width * 0.55, box.y + box.height * 0.5, { steps: 4 });
await page.waitForTimeout(300);
await revenue.screenshot({ path: '/tmp/hover-revenue.png' });

// hover по сегментной полосе
const sources = (await page.$$('.viz-widget'))[3];
const sb = await sources.boundingBox();
await page.mouse.move(sb.x + sb.width * 0.9, sb.y + sb.height * 0.55, { steps: 3 });
await page.waitForTimeout(300);
await sources.screenshot({ path: '/tmp/hover-sources.png' });
await browser.close();
console.log('ok');

